package com.example.transactionrecovery.service; import org.springframework.stereotype.Service; @Service public class EventDeliveryService {private final InMemoryEventBroker broker;private final SagaConsumer consumer;public EventDeliveryService(InMemoryEventBroker b,SagaConsumer c){broker=b;consumer=c;}public int consumeAvailable(){int n=0;for(var event=broker.poll();event!=null;event=broker.poll()){consumer.consume(event);n++;}return n;}}
